CREATE TABLE produto (id INTEGER PRIMARY KEY, estoque INTEGER);
CREATE TABLE venda (produto INTEGER, quantidade INTEGER);
CREATE TRIGGER baixa AFTER INSERT ON venda
FOR EACH ROW
BEGIN
  UPDATE produto SET estoque = estoque - NEW.quantidade
  WHERE id = NEW.produto;
END;
INSERT INTO produto VALUES (1, 50), (2, 30);
INSERT INTO venda VALUES (1, 8);
INSERT INTO venda VALUES (2, 5);
INSERT INTO venda VALUES (1, 12);
SELECT estoque FROM produto WHERE id = 1;

