CREATE TABLE funcionario (id INTEGER PRIMARY KEY, salario INTEGER);
CREATE TABLE historico (id INTEGER PRIMARY KEY, valor INTEGER);
CREATE TRIGGER guarda AFTER UPDATE ON funcionario
FOR EACH ROW
BEGIN
  INSERT INTO historico (valor) VALUES (OLD.salario);
END;
INSERT INTO funcionario VALUES (1, 1000);
UPDATE funcionario SET salario = 1200 WHERE id = 1;
UPDATE funcionario SET salario = 1500 WHERE id = 1;
SELECT valor FROM historico ORDER BY id DESC LIMIT 1;

