CREATE TABLE produto (id INTEGER PRIMARY KEY, preco INTEGER);
CREATE TABLE log (produto INTEGER);
CREATE TRIGGER audita AFTER UPDATE ON produto
FOR EACH ROW WHEN (OLD.preco <> NEW.preco)
BEGIN
  INSERT INTO log VALUES (NEW.id);
END;
INSERT INTO produto VALUES (1, 10), (2, 20), (3, 30);
UPDATE produto SET preco = 20 WHERE id <= 2;
UPDATE produto SET preco = preco + 5 WHERE id = 3;
UPDATE produto SET preco = 35;
SELECT COUNT(*) FROM log;

